const err = $input.first().json;
const msg = String(err.message ?? err.error ?? '');
const retryable = /timeout|timed out|429|rate limit|5\d\d|ECONN|ENOTFOUND|EAI_AGAIN|socket|overload|queue|temporarily/i.test(msg);
const permanent = /unauthor|forbidden|validation|invalid|not allowed|bad webhook secret|N8N_WEBHOOK_SECRET/i.test(msg);
return [{ json: {
  message: msg.slice(0, 500),
  retryable,
  permanent,
  workflow: (err.workflow && err.workflow.name) || 'product-video-main',
  node: (err.execution && err.execution.lastNodeExecuted) || (err.node && err.node.name) || 'unknown',
  hint: retryable ? 'Retryable — re-POST the webhook with the same idempotencyKey (backend dedupes).' : permanent ? 'Permanent — fix the input or config, then retry.' : 'Unclassified — check the n8n execution log.'
} }];

const e = $input.first().json;
console.error('[product-video-errors]', JSON.stringify(e));
return [{ json: { logged: true, at: new Date().toISOString(), ...e } }];
